{
  "marker": "TASK_COMPLETE",
  "carryover": {
    "COMPLETED": "Determined Apple stopped using the us-gaap Revenues concept after FY2018 and switched to the ASC 606 concept; tested and refuted alternative hypotheses.",
    "REMAINING": "",
    "DECISIONS": "H-c710de supported; H-b20b8d refuted; H-f3cf79 refuted; H-d7f2af refuted.",
    "CONTEXT": "Apple's revenue reporting changed after FY2018 due to ASC 606 adoption, not data loss or subsidiary-specific concepts."
  },
  "answer": {
    "summary": "Apple's revenue history under the us-gaap Revenues concept ends at FY2018 because Apple adopted the ASC 606 revenue recognition standard and began reporting revenue under the concept RevenueFromContractWithCustomerExcludingAssessedTax instead. The EDGAR pipeline is intact, as shown by IBM and Tesla continuing to report Revenues after FY2018, and there are no zero/null Revenues facts for Apple after FY2018. No other revenue-related concepts appear for Apple after FY2018, ruling out subsidiary-specific reporting.",
    "claims": [
      {"text": "Apple's latest Revenues fact is for fiscal year 2018.", "evidence": ["E-bdbb98"]},
      {"text": "Apple has zero Revenues facts for fiscal years 2019 through 2024.", "evidence": ["E-b549e1"]},
      {"text": "Apple reports revenue under the ASC 606 concept RevenueFromContractWithCustomerExcludingAssessedTax for fiscal years 2019-2024 (e.g., 21 facts in 2019, 21 in 2020, 13 in 2021-2024).", "evidence": ["E-f49a73"]},
      {"text": "IBM and Tesla have Revenues facts for fiscal years 2019-2024, showing the EDGAR pipeline works for other companies.", "evidence": ["E-dc2609"]},
      {"text": "Apple has no zero or null Revenues facts after FY2018.", "evidence": ["E-e6c8da"]},
      {"text": "After FY2018, Apple's only revenue-related concept used is RevenueFromContractWithCustomerExcludingAssessedTax; no other revenue concepts appear.", "evidence": ["E-cb7f4a"]}
    ],
    "inferences": [
      {"text": "The shift from Revenues to RevenueFromContractWithCustomerExcludingAssessedTax likely reflects Apple's adoption of ASC 606, which superseded the legacy revenue concept.", "basis": ["Claims about ASC 606 usage after FY2018 and cessation of Revenues."]},
      {"text": "Continued Revenues reporting by IBM and Tesla indicates the EDGAR ingestion pipeline is functional, making a pipeline-specific gap unlikely for Apple.", "basis": ["Claims about IBM/Tesla Revenues after FY2018."]}
    ],
    "hypothesis_verdicts": [
      {
        "id": "H-c710de",
        "status": "supported",
        "evidence": ["E-f49a73", "E-b549e1", "E-bdbb98"],
        "why": "Apple reports revenue under the ASC 606 concept after FY2018 and has no Revenues facts after FY2018, indicating a conceptual switch."
      },
      {
        "id": "H-b20b8d",
        "status": "refuted",
        "evidence": ["E-dc2609", "E-f49a73"],
        "why": "IBM and Tesla continue to have Revenues facts after FY2018, proving the pipeline works; Apple still reports revenue (via ASC 606 concept), so data are not missing."
      },
      {
        "id": "H-f3cf79",
        "status": "refuted",
        "evidence": ["E-e6c8da"],
        "why": "There are zero zero/null Revenues facts for Apple after FY2018, so the appearance of stopped reporting is not due to null/zero overrides."
      },
      {
        "id": "H-d7f2af",
        "status": "refuted",
        "evidence": ["E-cb7f4a"],
        "why": "After FY2018 Apple uses only the ASC 606 revenue concept; no other revenue-related (subsidiary-specific) concepts appear."
      }
    ]
  }
}
